export const GuardEvaluationSchema = z.strictObject({ conditionId: Id, result: z.enum(['satisfied', 'unsatisfied', 'unknown', 'conflict']), evidenceRefs: z.array(EvidenceRefSchema) });
export const MilestoneEvaluationSchema = z.strictObject({ milestoneId: Id, status: z.enum(['pending', 'in_progress', 'blocked', 'completed', 'not_applicable', 'waived']), guards: z.array(GuardEvaluationSchema), evidenceRefs: z.array(EvidenceRefSchema), blockers: z.array(BlockerSchema), workflowVersion: Id });
export type MilestoneEvaluation = z.infer<typeof MilestoneEvaluationSchema>;
export const WorkflowProgressSchema = z.strictObject({ workflowId: Id, workflowVersion: Id, milestones: z.array(MilestoneEvaluationSchema) });
export type WorkflowProgress = z.infer<typeof WorkflowProgressSchema>;
export const PolicyDecisionSchema = z.strictObject({ result: z.enum(['NEED_CLARIFICATION', 'READY_FOR_ADVISORY_CALL', 'HUMAN_REVIEW_REQUIRED', 'WAIT', 'STOP_CONTACT']), allowedActions: StringList, prohibitedActions: StringList, ruleIds: StringList, priority: z.number().int(), reviewRequired: z.boolean(), reasons: z.array(z.string()), evidenceRefs: z.array(EvidenceRefSchema) });
export type PolicyDecision = z.infer<typeof PolicyDecisionSchema>;
export const DecisionRecordSchema = z.strictObject({ decisionId: Id, inputEventIds: StringList, beforeRevision: Revision, afterRevision: Revision, factAssertionIds: StringList, evidenceRefs: z.array(EvidenceRefSchema), ruleIds: StringList, configBundleRef: ConfigBundleRefSchema, aiMode: z.enum(['openai', 'replay']), outcome: Id, warnings: z.array(z.string()) });
export type DecisionRecord = z.infer<typeof DecisionRecordSchema>;
export const CaseSnapshotSchema = z.strictObject({ caseId: Id, revision: Revision, messages: z.array(MessageSchema), assertions: z.array(FactAssertionSchema), knowledge: CaseKnowledgeSchema, goal: GoalSchema, workflowProgress: WorkflowProgressSchema, blockers: z.array(BlockerSchema), proposals: z.array(ActionProposalSchema), drafts: z.array(DraftSchema), events: z.array(CaseEventSchema), decisions: z.array(DecisionRecordSchema), configBundleRef: ConfigBundleRefSchema, status: z.enum(['NEEDS_ADVISOR', 'READY_TO_REPLY', 'WAITING_CUSTOMER', 'ON_HOLD_REVIEW', 'NEXT_STEP_AGREED', 'CLOSED', 'DO_NOT_CONTACT']), analysisStatus: z.enum(['pending', 'complete', 'analysis_failed']).optional() });
export type CaseSnapshot = z.infer<typeof CaseSnapshotSchema>;
export const CaseViewSchema = z.strictObject({ snapshot: CaseSnapshotSchema, activeProposal: ActionProposalSchema.nullable(), draft: DraftSchema.nullable(), errors: z.array(ApplicationErrorSchema), warnings: z.array(z.string()), aiMode: z.enum(['openai', 'replay']) });
export type CaseView = z.infer<typeof CaseViewSchema>;

/** Declarative configuration; cross-catalog references must be validated by the config loader. */
export const FieldDefinitionSchema = z.strictObject({ id: Id, label: Id, description: z.string(), type: z.enum(['text', 'enum', 'boolean', 'number', 'money', 'range', 'date', 'collection']), scopes: z.array(z.enum(['case', 'participant', 'buying_unit'])).min(1), cardinality: z.enum(['one', 'many']), units: StringList, enumOptions: StringList, sensitivity: z.enum(['normal', 'sensitive']), schemaVersion: Id });
export type FieldDefinition = z.infer<typeof FieldDefinitionSchema>;
export const FactSchemaSchema = z.strictObject({ id: Id, version: Id, fields: z.array(FieldDefinitionSchema) });
export type FactSchema = z.infer<typeof FactSchemaSchema>;
export type Condition = { id: string; op: 'fact_present' | 'fact_unambiguous'; fieldId: string } | { id: string; op: 'fact_matches'; fieldId: string; value: FactValue } | { id: string; op: 'event_confirmed'; eventType: CaseEvent['type'] } | { id: string; op: 'policy_result'; result: PolicyDecision['result'] } | { id: string; op: 'ALL' | 'ANY'; conditions: Condition[] };
export const ConditionSchema: z.ZodType<Condition> = z.lazy(() => z.discriminatedUnion('op', [
 z.strictObject({ id: Id, op: z.literal('fact_present'), fieldId: Id }),
 z.strictObject({ id: Id, op: z.literal('fact_unambiguous'), fieldId: Id }),
 z.strictObject({ id: Id, op: z.literal('fact_matches'), fieldId: Id, value: FactValueSchema }),
 z.strictObject({ id: Id, op: z.literal('event_confirmed'), eventType: z.enum(['MESSAGE_RECEIVED', 'CASE_ANALYSIS_REQUESTED', 'CASE_REEVALUATION_REQUESTED', 'FACT_CORRECTED', 'DRAFT_EDITED', 'DRAFT_APPROVED', 'DRAFT_DISCARDED', 'MESSAGE_SIMULATED_AS_SENT', 'CUSTOMER_CONFIRMED_NEXT_STEP', 'HUMAN_HANDOFF_CONFIRMED', 'DO_NOT_CONTACT_REQUESTED']) }),
 z.strictObject({ id: Id, op: z.literal('policy_result'), result: PolicyDecisionSchema.shape.result }),
 z.strictObject({ id: Id, op: z.literal('ALL'), conditions: z.array(ConditionSchema).min(1) }),
 z.strictObject({ id: Id, op: z.literal('ANY'), conditions: z.array(ConditionSchema).min(1) }),
]));
export const MilestoneDefinitionSchema = z.strictObject({ id: Id, purpose: Id, prerequisites: StringList, completion: ConditionSchema, applicability: ConditionSchema.optional(), onIncomplete: StringList, onBlocked: StringList, allowedSuccessors: StringList, terminalRoute: z.boolean(), evidencePolicy: StringList });
export type MilestoneDefinition = z.infer<typeof MilestoneDefinitionSchema>;
export const WorkflowDefinitionSchema = z.strictObject({ id: Id, version: Id, goal: Id, factSchemaVersion: Id, businessPolicyVersion: Id, milestones: z.array(MilestoneDefinitionSchema) });
export type WorkflowDefinition = z.infer<typeof WorkflowDefinitionSchema>;
export const AgentProfileSchema = z.strictObject({ id: Id, version: Id, role: Id, compatibleWorkflows: StringList, conversationStrategy: z.array(z.string()), decisionStrategy: z.array(z.string()), capabilities: StringList, contextStrategy: z.array(z.string()), communicationStyle: z.array(z.string()), fallbackBehavior: z.array(z.string()), observabilityHints: z.array(z.string()) });
export type AgentProfile = z.infer<typeof AgentProfileSchema>;
export const BusinessPolicySchema = z.strictObject({ id: Id, version: Id, synthetic: z.literal(true), advisoryCall: z.strictObject({ requireProductInterest: z.boolean(), requireLocation: z.boolean(), requireBuyerCount: z.boolean(), requireMovingHorizon: z.boolean(), requireSpecificMoveMonthBeforeCall: z.boolean(), requireDeclaredIncomeContext: z.boolean(), requireDeclaredSavings: z.boolean(), requireDisclosedDebtSemanticsResolved: z.boolean(), preventWhenCriticalBlockerOpen: z.boolean() }), financialApprovalEnabled: z.literal(false), ruleIds: StringList });
export type BusinessPolicy = z.infer<typeof BusinessPolicySchema>;
export const ReviewPolicySchema = z.strictObject({ id: Id, version: Id, protectedRuleIds: StringList, prohibitedClaims: z.array(z.string()) });
export type ReviewPolicy = z.infer<typeof ReviewPolicySchema>;
export const ActionCatalogSchema = z.strictObject({ id: Id, version: Id, actions: z.array(z.strictObject({ id: Id, description: Id, requiresDraft: z.boolean(), requiresHumanReview: z.boolean() })) });
export type ActionCatalog = z.infer<typeof ActionCatalogSchema>;
export const ConfigBundleSchema = z.strictObject({ workflow: WorkflowDefinitionSchema, factSchema: FactSchemaSchema, agentProfile: AgentProfileSchema, businessPolicy: BusinessPolicySchema, reviewPolicy: ReviewPolicySchema, actionCatalog: ActionCatalogSchema });
export type ConfigBundle = z.infer<typeof ConfigBundleSchema>;

/** Model output is candidate data, never an authoritative milestone or effect. */
export const InterpretationSchema = z.strictObject({ assertions: z.array(FactAssertionSchema), blockers: z.array(BlockerSchema), warnings: z.array(z.string()) });
export type Interpretation = z.infer<typeof InterpretationSchema>;
export interface Interpreter { interpret(input: { caseSnapshot: CaseSnapshot; messages: Message[]; factSchema: FactSchema; agentProfile: AgentProfile }): Promise<Result<Interpretation>> }
export interface DraftGenerator { generate(input: { caseSnapshot: CaseSnapshot; proposal: ActionProposal; agentProfile: AgentProfile; policyDecision: PolicyDecision }): Promise<Result<Draft>> }
export interface EventReceipt { eventId: string; caseId: string; revision: number }
export interface CaseRepository {
 get(caseId: string): Promise<Result<CaseSnapshot>>;
 saveIfRevision(snapshot: CaseSnapshot, expectedRevision: number): Promise<Result<CaseSnapshot>>;
 appendEvent(event: CaseEvent): Promise<Result<EventReceipt>>;
 reset(caseId: string): Promise<Result<CaseSnapshot>>;
}
