  if (event.type === 'HUMAN_HANDOFF_CONFIRMED' && event.actor !== 'advisor') return failure('INVALID_INPUT', 'La derivación requiere un asesor');
  if (event.type === 'DO_NOT_CONTACT_REQUESTED' && !event.payload.evidenceRefs.every(ref => snapshot.messages.some(m => m.messageId === ref.messageId && m.role === 'customer' && m.content.type === 'text'))) return failure('EVIDENCE_INVALID', 'La solicitud requiere evidencia del cliente');
